import { Component, HostListener, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { CatalogStatusFilter } from '../models/catalog-status-filter.model';
import { Category, CategoryPayload } from '../models/category.model';
import { CategoryService } from '../services/category.service';
import { ConfirmDialogService } from '../../../core/ui/confirm-dialog/confirm-dialog.service';
import { Icon } from '../../../core/ui/icon/icon';
import { StatusBadge } from '../../../core/ui/status-badge/status-badge';
import { ToastService } from '../../../core/ui/toast/toast.service';
import { resolveMediaUrl } from '../../../core/utils/resolve-media-url';
import { CategoryForm } from './category-form/category-form';

@Component({
  selector: 'app-category-management',
  imports: [FormsModule, Icon, StatusBadge, CategoryForm],
  templateUrl: './category-management.html',
  styleUrl: './category-management.scss',
})
export class CategoryManagement {
  protected readonly resolveMediaUrl = resolveMediaUrl;

  private readonly categoryService = inject(CategoryService);
  private readonly toast = inject(ToastService);
  private readonly confirmDialog = inject(ConfirmDialogService);

  protected readonly categories = signal<Category[]>([]);
  protected readonly loading = signal(true);
  protected readonly errorMessage = signal<string | null>(null);

  protected readonly searchTerm = signal('');
  protected readonly statusFilter = signal<CatalogStatusFilter>('all');

  protected readonly drawerOpen = signal(false);
  protected readonly editingCategory = signal<Category | null>(null);
  protected readonly viewMode = signal(false);
  protected readonly submitting = signal(false);

  protected readonly openMenuId = signal<number | null>(null);

  private searchDebounce?: ReturnType<typeof setTimeout>;

  constructor() {
    this.load();
  }

  @HostListener('document:click')
  closeMenus(): void {
    this.openMenuId.set(null);
  }

  onSearchChange(value: string): void {
    this.searchTerm.set(value);
    clearTimeout(this.searchDebounce);
    this.searchDebounce = setTimeout(() => this.load(), 350);
  }

  onStatusFilterChange(value: string): void {
    this.statusFilter.set(value as CatalogStatusFilter);
    this.load();
  }

  load(): void {
    this.loading.set(true);
    this.errorMessage.set(null);
    this.categoryService
      .list({ search: this.searchTerm() || undefined, estado: this.statusFilter() })
      .subscribe({
        next: (categories) => {
          this.categories.set(categories);
          this.loading.set(false);
        },
        error: () => {
          this.loading.set(false);
          this.categories.set([]);
          this.errorMessage.set(
            'No se pudo conectar con el servidor. Verifica que la API esté disponible e inténtalo nuevamente.',
          );
        },
      });
  }

  openCreate(): void {
    this.editingCategory.set(null);
    this.viewMode.set(false);
    this.drawerOpen.set(true);
  }

  openEdit(category: Category): void {
    this.openMenuId.set(null);
    this.editingCategory.set(category);
    this.viewMode.set(false);
    this.drawerOpen.set(true);
  }

  openView(category: Category, event: Event): void {
    event.stopPropagation();
    this.openMenuId.set(null);
    this.editingCategory.set(category);
    this.viewMode.set(true);
    this.drawerOpen.set(true);
  }

  closeDrawer(): void {
    this.drawerOpen.set(false);
  }

  toggleMenu(id: number, event: Event): void {
    event.stopPropagation();
    this.openMenuId.set(this.openMenuId() === id ? null : id);
  }

  save(payload: CategoryPayload): void {
    const editing = this.editingCategory();
    this.submitting.set(true);
    const request$ = editing
      ? this.categoryService.update(editing.id, payload)
      : this.categoryService.create(payload);

    request$.subscribe({
      next: () => {
        this.submitting.set(false);
        this.drawerOpen.set(false);
        this.toast.success(
          editing ? 'Categoría actualizada correctamente.' : 'Categoría creada correctamente.',
        );
        this.load();
      },
      error: (err) => {
        this.submitting.set(false);
        if (err.status === 409) {
          this.toast.error('Ya existe una categoría con ese nombre.');
        } else {
          this.toast.error('No se pudo guardar la categoría. Intenta nuevamente.');
        }
      },
    });
  }

  async toggleStatus(category: Category, event: Event): Promise<void> {
    event.stopPropagation();
    this.openMenuId.set(null);

    if (category.is_active) {
      const confirmed = await this.confirmDialog.confirm({
        title: '¿Desactivar categoría?',
        message: 'La categoría dejará de estar disponible para nuevas prendas.',
        confirmText: 'Desactivar',
        danger: true,
      });
      if (!confirmed) {
        return;
      }
    }

    this.categoryService.setActive(category.id, !category.is_active).subscribe({
      next: () => {
        this.toast.success(
          category.is_active ? 'Categoría desactivada.' : 'Categoría activada correctamente.',
        );
        this.load();
      },
      error: () => this.toast.error('No se pudo actualizar el estado de la categoría.'),
    });
  }

  async deleteCategory(category: Category, event: Event): Promise<void> {
    event.stopPropagation();
    this.openMenuId.set(null);

    const confirmed = await this.confirmDialog.confirm({
      title: '¿Eliminar categoría?',
      message: `Se eliminará permanentemente "${category.nombre}". Esta acción no se puede deshacer.`,
      confirmText: 'Eliminar',
      danger: true,
    });
    if (!confirmed) {
      return;
    }

    this.categoryService.delete(category.id).subscribe({
      next: () => {
        this.toast.success('Categoría eliminada correctamente.');
        this.load();
      },
      error: (err) => {
        if (err.status === 409) {
          this.toast.error('No se puede eliminar esta categoría porque existen productos asociados. Primero debe eliminar o desasociar los productos.');
        } else if (err.status === 404) {
          this.toast.error('La categoría no existe o ya fue eliminada.');
        } else {
          this.toast.error('No se pudo eliminar la categoría.');
        }
      },
    });
  }
}
